import{z as B,x as o,o as e,c as d,q as l,j as s,D as E,d as A,s as n,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"RAG 对微调","description":"","frontmatter":{"title":"RAG 对微调","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rag-vs-finetune.md","filePath":"llm/rag-vs-finetune.md","lastUpdated":1791063341000}'),p={name:"llm/rag-vs-finetune.md"};function D(m,a,F,C,h,T){const r=o("Mermaid");return e(),d("div",null,[a[2]||(a[2]=l('<h1 id="rag-对微调" tabindex="-1">RAG 对微调 <a class="header-anchor" href="#rag-对微调" aria-label="Permalink to &quot;RAG 对微调&quot;">​</a></h1><div class="epigraph"><p>私有知识要更新、要可引用、要能撤销，放索引。格式、语气、任务程序放权重。用微调背手册，过时与幻觉会绑在参数里。</p><footer>—— Ovadia 等对微调与检索的比较；Lewis 等 RAG 的非参数记忆</footer></div><p><a href="/llm/pq-vector-index">上一课</a>用子空间码本换内存，查询侧保持浮点，最终短列表用精确重排。索引已经能省；还要决定知识写在哪。缺口是 RAG 对微调的决策边界——避免「再训一遍就不用检索」。本课写这一边界，不重推 PQ 的码本。后课投毒防御默认：索引可被攻击，不等于该把知识熔进权重。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>微调能抬领域术语与答题格式，对<strong>封闭、稳定、不许外泄到提示</strong>的程序有效。对日期、价格、条款、内部工单，微调刚结束就过时，且无法逐条引用、无法按权限过滤。检索相反：更新是写文档，引用是块 ID，权限是元数据。代价是管道复杂、延迟、以及本单元写过的忠实度问题。</p><p>混合是常态：轻量 SFT 教会「如何用检索到的块作答」，知识仍在索引。用 SFT 把手册抄进权重，再加 RAG，会让参数与块冲突，归因更难。</p><p><span class="marginnote">长上下文窗口变大，不自动取消这道题。窗口是容量，索引是可更新集合与权限边界。见长上下文对 RAG 课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>决策表：变更频率高 → 索引；需引用与权限 → 索引；任务格式与工具规程稳定 → SFT / 指令。评测用时间切片：新文档进索引后未经微调是否立刻可答；过时文档删除后是否立刻不再被当事实。微调组应在同一切片上失败，才说明职责分对。</p><p><span class="marginnote">SFT（监督微调）就是「拿人工写好的问题–标准答案对，让模型照着学」的训法。这里的关键分工是：SFT 教的是手艺——拿到检索块后怎么引用、用什么格式作答；具体知识本身仍留在索引里，随时可换。</span></p>',10)),(e(),s(i,null,{default:E(()=>[n(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20KNOW%5B%22%E7%9F%A5%E8%AF%86%E7%B1%BB%E5%9E%8B%22%5D%20--%3E%20IDX%5B%22%E5%8F%AF%E6%9B%B4%E6%96%B0%20%2F%20%E8%A6%81%E5%BC%95%E7%94%A8%20%E2%86%92%20%E7%B4%A2%E5%BC%95%22%5D%0A%20%20KNOW%20--%3E%20WT%5B%22%E7%A8%B3%E5%AE%9A%E7%A8%8B%E5%BA%8F%20%2F%20%E6%A0%BC%E5%BC%8F%20%E2%86%92%20%E6%9D%83%E9%87%8D%22%5D%0A%20%20IDX%20--%3E%20PIPE%5B%22RAG%20%E7%AE%A1%E9%81%93%22%5D%0A%20%20WT%20--%3E%20SFT%5B%22SFT%20%E6%95%99%E5%A6%82%E4%BD%95%E7%94%A8%E5%9D%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[A("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"参数记忆是压缩过的统计，单条事实没有地址。非参数记忆有地址，才能撤销与审计。微调把新事实写入权重的同时，也扰动无关能力（灾难遗忘）。检索不扰动权重，但扰动上下文条件。冲突时阅读器需要明确指令「以块为准」，否则统计先验会赢。",-1)),(e(),s(i,null,{default:E(()=>[n(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20CHG%5B%22%E4%B8%80%E6%9D%A1%E4%BA%8B%E5%AE%9E%E5%8F%98%E4%BA%86%EF%BC%9A%E4%BB%B7%E6%A0%BC%2099%20%E5%85%83%E6%94%B9%E4%B8%BA%20199%20%E5%85%83%22%5D%20--%3E%20RAG%5B%22RAG%20%E8%B7%AF%EF%BC%9A%E6%94%B9%E7%B4%A2%E5%BC%95%E9%87%8C%E7%9A%84%E9%82%A3%E7%AF%87%E6%96%87%E6%A1%A3%22%5D%0A%20%20RAG%20--%3E%20ROK%5B%22%E4%B8%8B%E4%B8%80%E6%AC%A1%E6%8F%90%E9%97%AE%E5%8D%B3%E7%AD%94%20199%EF%BC%8C%E5%9D%97%20ID%20%E5%8F%AF%E5%BC%95%E7%94%A8%22%5D%0A%20%20CHG%20--%3E%20FT%5B%22%E5%BE%AE%E8%B0%83%E8%B7%AF%EF%BC%9A%E9%87%8D%E6%96%B0%E6%94%B6%E9%9B%86%E6%95%B0%E6%8D%AE%EF%BC%8C%E5%86%8D%E8%AE%AD%E4%B8%80%E8%BD%AE%22%5D%0A%20%20FT%20--%3E%20FOLD%5B%22%E6%97%A7%E7%AD%94%E6%A1%88%2099%20%E4%BB%8D%E6%AE%8B%E7%95%99%E5%9C%A8%E6%9D%83%E9%87%8D%E9%87%8C%22%5D%0A%20%20FOLD%20--%3E%20RISK%5B%22%E6%97%A0%E6%B3%95%E9%80%90%E6%9D%A1%E6%92%A4%E9%94%80%EF%BC%8C%E4%B9%9F%E6%B2%A1%E6%B3%95%E6%8C%87%E8%AE%A4%E9%94%99%E5%9C%A8%E5%93%AA%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=l('<p><span class="marginnote">这张图回答「一条事实变更后，两条路各自会发生什么」。注意微调路的滞后不只是慢：旧价格没有任何「地址」可删，它散布在几亿个参数里，你既不能精确改掉它，也不能证明它已经不影响输出。</span></p><p><span class="marginnote">灾难遗忘可以理解成「学新忘旧」：训练新数据时权重整体被推动，原来会的能力可能悄悄退化——比如补完领域问答后，代码能力莫名下滑。它不报错、不留日志，只能靠定期回测老任务才发现。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>极小语料、极强保密、禁止任何文档出域时，可能只能微调且不上检索——那是约束，不是精度更优。下一课：索引可写意味着对手也可写，需要投毒防御。</p><p><span class="marginnote">这一步判断做错的后果很具体：把日更的价格表微调进权重，每次调价都要重训、重发布，而且永远说不清「旧价格存在哪个参数里、清干净了没有」。保密约束下的选择要明说「这是约束」，别包装成技术最优。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>可更新、可引用、要权限的知识放索引；稳定程序放权重。</li><li>SFT 应教「如何用块」，而不是把手册背进参数。</li><li>用时间切片验收更新与撤销。</li><li>出处：Ovadia 等微调对检索；Lewis 等 RAG。</li></ul>',7))])}const f=B(p,[["render",D]]);export{c as __pageData,f as default};
